import { defineConfig, devices } from "@playwright/test";

// Boots a Gust app generated by setup_gust_app.sh and runs the e2e suite
// against it. GUST_APP_DIR points at the generated app; GUST_E2E_MODE picks
// whether to boot it with `mix phx.server` (dev) or its release (prod).
const appDir = process.env.GUST_APP_DIR;
if (!appDir) throw new Error("GUST_APP_DIR must point at the generated Gust app");

const app = process.env.GUST_APP ?? "gust_generated_app";
const mode = process.env.GUST_E2E_MODE ?? "dev";
const port = Number(process.env.PORT ?? 4000);

export default defineConfig({
  testDir: "./tests",
  // The suite shares one server and one database; run it serially.
  workers: 1,
  timeout: 120_000,
  reporter: [["list"]],
  use: {
    baseURL: `http://localhost:${port}`,
    trace: "retain-on-failure",
  },
  projects: [{ name: "chromium", use: { ...devices["Desktop Chrome"] } }],
  webServer: {
    command: mode === "prod" ? `_build/prod/rel/${app}/bin/${app} start` : "mix phx.server",
    cwd: appDir,
    url: `http://localhost:${port}/gust/dags`,
    reuseExistingServer: false,
    timeout: 180_000,
    stdout: "pipe",
    stderr: "pipe",
    env: { PORT: String(port) },
  },
});
